# region: shape
def shape(raw):
    out = []
    for tok in raw[1:]:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: sift
def sift(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: render
def render(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(render(sift(intake(shape(raw)))))

